  # write_input_packet packs value into a fresh binary — the trusted writer; the O(1)
  # contract checks raise ArgumentError, always on (the BEAM has no
  # compile-out assert). Returns the wire bytes.
  def write_input_packet(value) do
    data = <<>>

    %{
      synchronize_sequence: value_synchronize_sequence,
      current_frame: value_current_frame,
      start_frame: value_start_frame,
      inputs: value_inputs
    } = value

    v = value_synchronize_sequence &&& 0xFFFF
    scratch = v
    v = value_current_frame &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< 16
    v = value_current_frame >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    scratch = v
    v = value_start_frame &&& 0xFFFFFFFF
    sc1 = scratch
    scratch = v
    v = value_start_frame >>> 32 &&& 0xFFFFFFFF
    sc2 = scratch
    scratch = v
    n = length(value_inputs)

    if n > 16 do
      raise ArgumentError, "value.inputs count is above the wire maximum"
    end

    v = n
    scratch = scratch ||| v <<< 32

    data =
      <<data::binary, sc0::little-size(6)-unit(8), sc1::little-size(4)-unit(8),
        sc2::little-size(4)-unit(8), scratch::little-size(4)-unit(8)>>

    scratch = scratch >>> 32
    scratch_bits = 5

    {data, scratch, scratch_bits} =
      w_input_packet_inputs(value_inputs, data, scratch, scratch_bits)

    if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
  end

